from pathlib import Path
import subprocess
root=Path('角色库/露西/形象/文字探索')
common='''Create a completely original character design from this text only. No reference images. One young adult woman named Lucy, an ordinary waitress in a 1940s-1950s American working-class harbor cafe in a film noir story. She is lively, curious, sincere, a little impulsive, competent at serving, interested in detective stories, saving money for typing night school. Give her individual character and everyday warmth. Natural adult anatomy, about 7 heads tall, not anime, not pinup, not glamorous. Period-correct practical waitress clothing, no French maid costume, no frills, no modern sneakers. Full body, both shoes visible, single character on square pure black background, no scenery or text or watermark. Draw entirely using luminous clean bright WHITE CONTOUR LINES, very restrained glow, minimal essential inner lines. ALL skin, face, hair and clothes interiors PURE BLACK negative space. No white filled face or apron, no gray shading, no solid colored areas, no hatching. Tiny amber accent on a pencil only. Readable silhouette at small gameplay size. Comfortable grounded stance, never crossed fashion-model legs. Leave margins around entire figure.\n'''
variants={
'A_轻快机灵':'''Design direction A: quick-witted, playful curiosity. Compact slim but healthy build, lively face with slightly upturned nose and asymmetrical amused smile. Short softly curled bob ending near jaw, side part held by a plain small barrette. Practical short-sleeve small rounded collar waitress shirt dress, gently flared knee-length skirt and simple half apron, flat lace-up work shoes. Slight forward lean and curious head tilt as if asking a detective another question. One hand carries a small empty serving tray at waist, other hand has a pencil poised above a small order pad. Folded newspaper in apron pocket. Energetic silhouette with short rounded hair and outward tray gesture. Do not use a seductive pose.''',
'B_爽朗干练':'''Design direction B: cheerful, brisk, capable and direct, with unpolished neighborhood charm. Sturdy healthy average build, slightly broader shoulders, rounder face, open restrained grin and confident attentive eyes. Wavy hair pulled back into a small practical low ponytail with a narrow cloth tie, one escaped curl at forehead. Sleeves rolled to just above elbows, simple pointed shirt collar, straight button-front knee-length work dress, long utilitarian waist apron with broad pocket, flat sturdy oxford shoes. Feet planted apart naturally, torso turned three-quarter, shoulders relaxed. One hand holds a period coffee pot low beside hip, other hand on apron pocket showing a folded job advertisement and pencil. She looks ready to tease a coworker and get the next table served. Not muscular, not stern, not elegant society lady. Distinct sturdy grounded silhouette.''',
'C_文静好奇':'''Design direction C: quieter thoughtful curiosity, shy wit and hopeful determination, still friendly and youthful. Average slim build, soft oval face, small warm half-smile, alert inquisitive eyes. Medium wavy hair neatly pinned into a modest low bun, a loose cheek-length curl, no hat. Simple short-sleeve square-neck modest work dress over a visible small collared blouse insert, below-knee A-line skirt, tidy practical bib apron with a small square pocket, plain low-heel strap work shoes. Standing naturally with feet uncrossed, body three-quarter turned, gaze lifted toward someone speaking offscreen. Hold a folded newspaper and short pencil loosely at waist with both hands, as if interrupted while circling a typing-school notice during a break. Newspaper has only sparse abstract lines, no legible words. An ordinary working woman with a private ambition, not timid helplessness, not schoolgirl or glamorous femme fatale. Distinct bun and bib-apron silhouette.'''
}
for name,desc in variants.items():
    prompt=root/(name+'-prompt.txt')
    prompt.write_text(common+desc+'\n')
    result=subprocess.run(['node','tools/gemini-image-web/gemini-image-web.mjs','generate','--prompt-file',str(prompt),'--out',str(root/(name+'.png'))])
    if result.returncode: raise SystemExit(result.returncode)
